--
-- Table structure for table `schedule_sessions`
--

DROP TABLE IF EXISTS `schedule_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedule_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `schedule_version_id` bigint unsigned NOT NULL,
  `course_offering_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `mode` enum('offline','online','unscheduled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'offline',
  `day_of_week` tinyint unsigned DEFAULT NULL,
  `start_minute` smallint unsigned DEFAULT NULL,
  `end_minute` smallint unsigned DEFAULT NULL,
  `room_id` bigint unsigned DEFAULT NULL,
  `phase` enum('full','before_uts','after_uts') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'full',
  `source_file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_row` int unsigned DEFAULT NULL,
  `source_raw` json DEFAULT NULL,
  `is_locked` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `schedule_sessions_course_offering_id_foreign` (`course_offering_id`),
  KEY `schedule_sessions_room_id_foreign` (`room_id`),
  KEY `schedule_sessions_schedule_version_id_day_of_week_index` (`schedule_version_id`,`day_of_week`),
  CONSTRAINT `schedule_sessions_course_offering_id_foreign` FOREIGN KEY (`course_offering_id`) REFERENCES `course_offerings` (`id`) ON DELETE SET NULL,
  CONSTRAINT `schedule_sessions_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `schedule_sessions_schedule_version_id_foreign` FOREIGN KEY (`schedule_version_id`) REFERENCES `schedule_versions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2535 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `schedule_sessions`
--

LOCK TABLES `schedule_sessions` WRITE;
/*!40000 ALTER TABLE `schedule_sessions` DISABLE KEYS */;
